return items.map((item) => {
  const body = item.json.body || item.json || {};
  const headers = item.json.headers || {};
  const authHeader = String(headers.authorization || headers.Authorization || '').trim();
  const expectedApiKey = String($env.SMS_API_KEY_RICARDO_VALE_RICARDO_VALE || $env.SMS_API_KEY || '').trim();
  const errors = [];

  if (expectedApiKey && authHeader !== `Bearer ${expectedApiKey}`) {
    errors.push('Authorization Bearer invalido para o gateway SMS.');
  }

  const phoneDigits = String(body.to || '').replace(/\D/g, '');
  const normalizedTo = phoneDigits.startsWith('55') ? phoneDigits : (phoneDigits.length >= 10 && phoneDigits.length <= 11 ? `55${phoneDigits}` : phoneDigits);
  const message = String(body.message || body.mensagem || '').trim().slice(0, 320);
  const requestedIdCandidato = String(body.idCandidato || body.id_candidato || '').trim();
  const idCandidato = 'ricardo-vale';
  const dispatchId = String(body.dispatchId || body.dispatch_id || '').trim();
  const sender = String(body.from || body.senderId || body.sender_id || $env.SMS_SENDER_ID_RICARDO_VALE_RICARDO_VALE || $env.SMS_SENDER_ID || '').trim();
  const provider = String(body.provider || $env.SMS_PROVIDER_RICARDO_VALE_RICARDO_VALE || $env.SMS_PROVIDER || 'webhook').trim();
  const gatewayUrl = String($env.SMS_GATEWAY_URL_RICARDO_VALE_RICARDO_VALE || $env.SMS_GATEWAY_URL || '').trim();
  const dryRun = ['true', '1', 'sim', 'yes'].includes(String($env.SMS_GATEWAY_DRY_RUN_RICARDO_VALE_RICARDO_VALE || $env.SMS_GATEWAY_DRY_RUN || '').trim().toLowerCase());

  if (!normalizedTo || normalizedTo.length < 10) errors.push('Telefone destino ausente ou invalido.');
  if (!message) errors.push('Mensagem SMS ausente.');
  if (requestedIdCandidato && requestedIdCandidato !== idCandidato) errors.push('idCandidato divergente para este workflow.');

  const valido = errors.length === 0;
  return {
    json: {
      valido,
      autorizado: !expectedApiKey || authHeader === `Bearer ${expectedApiKey}`,
      statusCode: valido ? 200 : (errors.some((error) => error.includes('Authorization')) ? 401 : 400),
      errors,
      provider,
      gateway_url_configurado: Boolean(gatewayUrl),
      dry_run: dryRun,
      dispatchId,
      idCandidato,
      from: sender,
      to: normalizedTo,
      nome: body.nome || null,
      message,
      raw: body
    }
  };
});

return items.map((item) => ({
  json: {
    status: 'ok',
    provider: item.json.provider || 'gateway',
    dispatchId: item.json.dispatchId,
    idCandidato: item.json.idCandidato,
    to: item.json.to,
    enviado: true,
    message: 'SMS encaminhado ao gateway configurado.'
  }
}));
